<script setup lang="ts">
import {computed,ref} from 'vue';
import type {PositionBlueprintView,PositionCompetitionView,TeamSummary} from '@torneos/shared';
import SportTabs from './SportTabs.vue';
import PositionTieResolver from './PositionTieResolver.vue';

const props=defineProps<{view:PositionBlueprintView;competition:PositionCompetitionView|null;entries:TeamSummary[];organizationId:string;canManage:boolean}>();
const emit=defineEmits<{decideTitleExtra:[input:{decision:'no_extra'|'extra';homeEntryId?:string;awayEntryId?:string}];decideTiebreak:[input:{table:'A'|'B'|'general';position:number;entryOrder:string[]}]}>();
const tab=ref('groups');
const groupTab=ref<'A'|'B'>('A');
const chosen=ref<string[]>([]);
const slots=computed(()=>new Map(props.view.slots.map(slot=>[slot.slot_code,slot])));
const quarterfinals=computed(()=>props.view.games.filter(game=>game.stage==='quarterfinal'));
const quadrangular=computed(()=>props.view.games.filter(game=>game.stage==='quadrangular'));
function name(code:string){return slots.value.get(code)?.team_name||(/^[1-4][AB]$/.test(code)?`${code[0]}.º Grupo ${code[1]}`:/^S[1-4]$/.test(code)?`${code[1]}.º entre los ganadores`:code);}
function crest(code:string){const assigned=slots.value.get(code);const team=props.entries.find(item=>item.entry_id===assigned?.entry_id);return team?.has_shield?`/api/v1/organizations/${props.organizationId}/teams/${team.id}/shield`:null;}
function date(date:string|null){if(!date)return '';const [y,m,d]=date.slice(0,10).split('-');return `${d}/${m}`;}
const results=computed(()=>new Map((props.competition?.results||[]).map(result=>[result.code,result])));
const matches=computed(()=>new Map((props.competition?.matches||[]).map(match=>[match.code,match])));
function teamName(id:string|null){return props.entries.find(entry=>entry.entry_id===id)?.name||'Por definir';}
function pairName(code:string,side:'home'|'away',fallback:string){const id=props.competition?.competition.participants[code]?.[side==='home'?'homeEntryId':'awayEntryId'];return id?teamName(id):name(fallback);}
function crestEntry(id:string){const team=props.entries.find(item=>item.entry_id===id);return team?.has_shield?`/api/v1/organizations/${props.organizationId}/teams/${team.id}/shield`:null;}
function tableRows(table:NonNullable<PositionCompetitionView['competition']['final']>){return table.groups.flatMap(group=>group.teamIds.map(id=>({position:group.position,id,unresolved:group.unresolved,stats:table.totals.find(row=>row.teamId===id)})));}
const scorers=computed(()=>[...(props.competition?.players||[])].filter(player=>player.goals>0).sort((a,b)=>b.goals-a.goals||a.name.localeCompare(b.name)));
const defense=computed(()=>[...(props.competition?.defense||[])].filter(item=>item.played>0).sort((a,b)=>a.goalsAgainst-b.goalsAgainst||a.played-b.played));
function toggleTitleTeam(id:string){chosen.value=chosen.value.includes(id)?chosen.value.filter(item=>item!==id):[...chosen.value.slice(-1),id];}
function chooseExtra(){const tied=props.competition?.titleTie||[];const pair=chosen.value.length===2?chosen.value:tied.length===2?tied:[];if(pair.length===2)emit('decideTitleExtra',{decision:'extra',homeEntryId:pair[0],awayEntryId:pair[1]});}
</script>

<template>
  <section class="position-stats">
    <SportTabs v-model="tab" :tabs="[{key:'groups',label:'Grupos',icon:'users'},{key:'general',label:'General',icon:'chart'},{key:'quarterfinals',label:'Cuartos',icon:'trophy'},{key:'quadrangular',label:'Finales',icon:'shield'},{key:'scorers',label:'Goleadores',icon:'ball'},{key:'defense',label:'Valla',icon:'shield'}]" id="copa-stats" />
    <div class="position-stats-body">
      <div v-if="tab==='groups'" id="copa-stats-groups-panel" role="tabpanel" aria-labelledby="copa-stats-groups-tab"><div class="position-group-tabs" role="group" aria-label="Elegir grupo"><button v-for="group in ['A','B'] as const" :key="group" type="button" :aria-pressed="groupTab===group" @click="groupTab=group">Grupo {{ group }}</button></div><section v-for="group in ['A','B'] as const" v-show="groupTab===group" :key="group"><template v-if="competition?.competition.official.groups"><div v-for="row in tableRows(group==='A'?competition.competition.groupA:competition.competition.groupB)" :key="row.id" class="position-stats-table-row"><b>{{ row.unresolved?'=':row.position }}</b><img v-if="crestEntry(row.id)" :src="crestEntry(row.id)!" alt=""><span v-else class="position-stats-mark">{{ group }}</span><strong>{{ teamName(row.id) }}</strong><small>{{ row.stats?.played }} PJ</small><span>{{ row.stats?.goalDifference }} DG</span><b>{{ row.stats?.points }}</b></div><PositionTieResolver v-if="canManage&&competition.competition.official.groups===25" v-for="tie in (group==='A'?competition.competition.groupA:competition.competition.groupB).groups.filter(item=>item.unresolved)" :key="`${group}-${tie.position}`" :team-ids="tie.teamIds" :position="tie.position" :entries="entries" :disabled="!canManage" @save="entryOrder=>emit('decideTiebreak',{table:group,position:tie.position,entryOrder})" /></template><template v-else><div v-for="slot in view.slots.filter(item=>item.slot_code.startsWith(group))" :key="slot.slot_code" class="position-stats-team"><b>{{ slot.slot_code }}</b><img v-if="crest(slot.slot_code)" :src="crest(slot.slot_code)!" alt=""><span v-else class="position-stats-mark">{{ group }}</span><strong>{{ slot.team_name||'Por sortear' }}</strong></div></template></section></div>
      <div v-else-if="tab==='general'" id="copa-stats-general-panel" role="tabpanel" aria-labelledby="copa-stats-general-tab"><h2>Tabla general · primera etapa</h2><div v-if="!competition?.competition.official.groups" class="position-stats-empty">Aún sin resultados oficiales.</div><div v-for="row in competition?.competition.official.groups?tableRows(competition.competition.general):[]" :key="row.id" class="position-stats-table-row"><b>{{ row.unresolved?'=':row.position }}</b><img v-if="crestEntry(row.id)" :src="crestEntry(row.id)!" alt=""><span v-else class="position-stats-mark">•</span><strong>{{ teamName(row.id) }}</strong><small>{{ row.stats?.played }} PJ</small><span>{{ row.stats?.goalDifference }} DG</span><b>{{ row.stats?.points }}</b></div><PositionTieResolver v-if="canManage&&competition?.competition.official.groups===25" v-for="tie in competition?.competition.general.groups.filter(item=>item.unresolved)||[]" :key="`general-${tie.position}`" :team-ids="tie.teamIds" :position="tie.position" :entries="entries" :disabled="!canManage" @save="entryOrder=>emit('decideTiebreak',{table:'general',position:tie.position,entryOrder})" /></div>
      <div v-else-if="tab==='quarterfinals'" id="copa-stats-quarterfinals-panel" role="tabpanel" aria-labelledby="copa-stats-quarterfinals-tab"><h2>Cuartos</h2><div v-for="game in quarterfinals" :key="game.code" class="position-stats-game"><small>Llave {{ game.code.slice(2) }} · J{{ game.jornada_no }} · {{ date(game.planned_date) }}</small><strong>{{ pairName(game.code,'home',game.home_ref) }} <em>{{ results.get(game.code)?`${results.get(game.code)!.homeGoals}:${results.get(game.code)!.awayGoals}`:'vs' }}</em> {{ pairName(game.code,'away',game.away_ref) }}</strong><a v-if="matches.get(game.code)" :href="`#/partido/${matches.get(game.code)!.match_id}`">Abrir partido ›</a></div></div>
      <div v-else-if="tab==='quadrangular'" id="copa-stats-quadrangular-panel" role="tabpanel" aria-labelledby="copa-stats-quadrangular-tab">
        <h2>Finales</h2>
        <div v-if="competition?.competition.final&&competition.competition.official.quadrangular" class="position-stats-final"><div v-for="row in tableRows(competition.competition.final)" :key="row.id" class="position-stats-table-row"><b>{{ row.unresolved?'=':row.position }}</b><img v-if="crestEntry(row.id)" :src="crestEntry(row.id)!" alt=""><span v-else class="position-stats-mark">•</span><strong>{{ teamName(row.id) }}</strong><small>{{ row.stats?.played }} PJ</small><span>{{ row.stats?.goalDifference }} DG</span><b>{{ row.stats?.points }}</b></div></div>
        <div v-for="game in quadrangular" :key="game.code" class="position-stats-game"><small>Fecha {{ game.sporting_round.slice(-1) }} · J{{ game.jornada_no }} · {{ date(game.planned_date) }}</small><strong>{{ pairName(game.code,'home',game.home_ref) }} <em>{{ results.get(game.code)?`${results.get(game.code)!.homeGoals}:${results.get(game.code)!.awayGoals}`:'vs' }}</em> {{ pairName(game.code,'away',game.away_ref) }}</strong><a v-if="matches.get(game.code)" :href="`#/partido/${matches.get(game.code)!.match_id}`">Abrir partido ›</a></div>
        <div v-if="competition?.titleTie.length && competition.titleTie.length>1" class="position-title-extra">
          <h2>Empate por el título</h2>
          <div v-if="competition.titleExtra?.decision==='extra'" class="position-stats-game"><strong>{{ teamName(competition.titleExtra.homeEntryId) }} <em>{{ competition.titleExtra.score?`${competition.titleExtra.score.home}:${competition.titleExtra.score.away}`:'vs' }}</em> {{ teamName(competition.titleExtra.awayEntryId) }}</strong><small v-if="competition.titleExtra.score?.home===competition.titleExtra.score?.away && competition.titleExtra.score?.homePenalties!==competition.titleExtra.score?.awayPenalties">Penales {{ competition.titleExtra.score?.homePenalties }}:{{ competition.titleExtra.score?.awayPenalties }}</small><b v-if="competition.titleExtra.winnerEntryId">Campeón: {{ teamName(competition.titleExtra.winnerEntryId) }}</b><a v-if="competition.titleExtra.matchId" :href="`#/partido/${competition.titleExtra.matchId}`">Abrir partido ›</a></div>
          <span v-if="competition.titleExtra?.decision==='no_extra'" class="position-stats-empty">Sin partido extra</span>
          <template v-if="canManage"><div v-if="competition.titleTie.length>2" class="position-title-choices"><button v-for="id in competition.titleTie" :key="id" type="button" :aria-pressed="chosen.includes(id)" @click="toggleTitleTeam(id)">{{ teamName(id) }}</button></div><div class="position-title-actions"><button type="button" @click="emit('decideTitleExtra',{decision:'no_extra'})">Sin extra</button><button type="button" :disabled="competition.titleTie.length>2&&chosen.length!==2" @click="chooseExtra">Crear partido extra</button></div></template>
        </div>
      </div>
      <div v-else-if="tab==='scorers'" id="copa-stats-scorers-panel" role="tabpanel" aria-labelledby="copa-stats-scorers-tab"><h2>Goleadores</h2><div v-if="!scorers.length" class="position-stats-empty">Aún sin goles oficiales atribuidos.</div><div v-for="(player,index) in scorers" :key="player.registrationId" class="position-stats-scorer"><b>{{ index+1 }}</b><strong>{{ player.name }}<small>{{ teamName(player.entryId) }}</small></strong><b>⚽ {{ player.goals }}</b></div></div>
      <div v-else id="copa-stats-defense-panel" role="tabpanel" aria-labelledby="copa-stats-defense-tab"><h2>Valla menos vencida</h2><div v-if="!defense.length" class="position-stats-empty">Aún sin partidos oficiales.</div><div v-for="(row,index) in defense" :key="row.entryId" class="position-stats-scorer"><b>{{ index+1 }}</b><strong>{{ teamName(row.entryId) }}<small>{{ row.played }} PJ</small></strong><b>{{ row.goalsAgainst }} GC</b></div></div>
    </div>
  </section>
</template>

<style scoped>
.position-group-tabs{display:flex;gap:4px;margin:7px 0 9px;border-bottom:1px solid #dce8e0}.position-group-tabs button{min-height:42px;padding:7px 15px;border:0;border-bottom:2px solid transparent;background:transparent;color:#617970;font:inherit;font-size:.75rem;font-weight:700}.position-group-tabs button[aria-pressed=true]{border-color:#08714c;color:#075e40}.position-group-tabs button:focus-visible{outline:3px solid #165dad;outline-offset:-3px}
.position-stats{max-width:880px;margin:auto;background:#fff}.position-stats-body{padding:5px 0 32px}.position-stats-body h2{margin:12px 0 7px;font-size:.84rem}.position-stats-body p,.position-stats-empty{margin:10px 0;color:#617970;font-size:.76rem;line-height:1.45}.position-stats-team{display:flex;align-items:center;gap:8px;min-height:45px;border-top:1px solid #e5ede8;font-size:.78rem}.position-stats-team>b{width:27px;color:#08714c}.position-stats-team img,.position-stats-mark{display:grid;place-items:center;flex:none;width:27px;height:27px;object-fit:contain;border-radius:50%;background:#e5eee9;color:#086040;font-size:.6rem;font-weight:800}.position-stats-team strong{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.position-stats-game{padding:12px 0;border-top:1px solid #e5ede8}.position-stats-game small{display:block;color:#20724e;font-size:.67rem;font-weight:750}.position-stats-game strong{display:block;margin-top:4px;font-size:.78rem}.position-stats-game em{color:#7a8c83;font-size:.7rem;font-style:normal;font-weight:500}
.position-stats-table-row{display:grid;grid-template-columns:20px 27px minmax(0,1fr) 32px 38px 25px;gap:5px;align-items:center;min-height:45px;border-top:1px solid #e5ede8;font-size:.72rem}.position-stats-table-row strong{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.position-stats-table-row b{color:#075e40}.position-stats-table-row small,.position-stats-table-row>span:not(.position-stats-mark){color:#657a70;text-align:right;font-size:.65rem}.position-stats-table-row>b:last-child{text-align:right}.position-stats-scorer{display:grid;grid-template-columns:23px minmax(0,1fr) auto;gap:8px;align-items:center;min-height:52px;border-top:1px solid #e5ede8;font-size:.78rem}.position-stats-scorer>b{color:#08714c}.position-stats-scorer strong{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.position-stats-scorer small{display:block;color:#678076;font-size:.67rem;font-weight:500}.position-stats-game a{display:inline-flex;align-items:center;min-height:36px;color:#08714c;text-decoration:none;font-size:.69rem;font-weight:700}
.position-title-extra{margin-top:18px;border-top:2px solid #0b704e;padding-top:5px}.position-title-actions,.position-title-choices{display:flex;flex-wrap:wrap;gap:7px;margin-top:9px}.position-title-actions button,.position-title-choices button{min-height:44px;padding:8px 12px;border:1px solid #cdded4;border-radius:8px;background:#fff;color:#0a6246;font:inherit;font-size:.74rem;font-weight:700}.position-title-actions button:last-child,.position-title-choices button[aria-pressed=true]{background:#0b704e;color:#fff}.position-title-actions button:disabled{opacity:.45}
</style>
